import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.databind.JsonSerializer;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializerProvider;
import com.fasterxml.jackson.databind.module.SimpleModule;
import java.io.IOException;

public class Example {
    public static class Money {
        public final String amount = "10.50";
        public final String currency = "USD";
    }

    public static class MoneySerializer extends JsonSerializer<Money> {
        @Override
        public void serialize(Money m, JsonGenerator gen, SerializerProvider provider) throws IOException {
            gen.____(m.amount + " " + m.currency);
        }
    }

    public static void main(String[] args) throws Exception {
        SimpleModule module = new SimpleModule();
        module.addSerializer(Money.class, new MoneySerializer());
        ObjectMapper mapper = new ObjectMapper().registerModule(module);
        System.out.println(mapper.writeValueAsString(new Money()));
    }
}

import com.fasterxml.jackson.annotation.JsonSubTypes;
import com.fasterxml.jackson.annotation.JsonTypeInfo;
import com.fasterxml.jackson.databind.ObjectMapper;

public class Example {
    @JsonTypeInfo(use = JsonTypeInfo.Id.NAME, property = "type")
    @JsonSubTypes({
        @JsonSubTypes.Type(value = Dog.class, name = "dog"),
        @JsonSubTypes.Type(value = Cat.class, name = "cat")
    })
    public static abstract class Animal { }

    public static class Dog extends Animal {
        public String name = "Rex";
    }

    public static class Cat extends Animal {
        public int lives = 9;
    }

    public static void main(String[] args) throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        Animal a = new Dog();
        Animal b = mapper.readValue("{\"type\":\"cat\",\"lives\":7}", Animal.class);
        System.out.println(mapper.writeValueAsString(a) + " "
                + b.getClass().getSimpleName() + " " + ((Cat) b).lives);
    }
}

